package dev.industrialtechnology.railway;
import java.util.*;import net.minecraft.entity.player.EntityPlayer;import net.minecraft.item.ItemStack;import net.minecraft.nbt.NBTTagCompound;import net.minecraft.util.ChatComponentText;import dev.industrialtechnology.expansion.ExpansionConfig;
public final class RailCoupling {
 public static String connect(EntityRollingStock head,EntityRollingStock tail,EntityPlayer p){if(head==tail||!head.permitted(p)||!tail.permitted(p))return "You must own both vehicles.";if(head.speed>.001||tail.speed>.001)return "Stop both vehicles first.";if(head.rear!=null||tail.front!=null||tail.stock.engine())return "Select a free rear coupler, then an uncoupled wagon.";if(tail.consist().contains(head)||head.consist().size()+tail.consist().size()>ExpansionConfig.maxWagons+1)return "Coupling cycle or wagon limit.";if(head.rail==null||tail.rail==null)return "Both vehicles must be on rails.";TrackWorld.Cursor target=head.rail.copy();double spacing=(head.stock.length+tail.stock.length)/2+.8;if(!target.move(head.worldObj,-spacing))return "There is insufficient connected track behind this vehicle.";double[] a=target.point(head.worldObj);if(a==null||RailPath.distance(a,tail.posX,tail.posY,tail.posZ)>4)return "Position the wagon within 2 m of the rear coupler.";head.rear=tail.getUniqueID();tail.front=head.getUniqueID();head.worldObj.playSoundAtEntity(head,"industrialtech:coupler",.7f,1);return "Coupled. Wagons retain their own rail positions.";}
 public static void use(EntityPlayer p,EntityRollingStock e){ItemStack tool=p.getHeldItem();if(!e.permitted(p))return;if(p.isSneaking()){EntityRollingStock r=RailwayWorld.get(e.worldObj,e.rear);if(e.speed>.001){say(p,"Stop before uncoupling.");return;}if(r!=null){r.front=null;r.brake=1;e.rear=null;say(p,"Rear wagon uncoupled.");}else say(p,"No loaded rear wagon.");return;}NBTTagCompound n=tool.getTagCompound();if(n==null){n=new NBTTagCompound();tool.setTagCompound(n);}if(!n.hasKey("Selected")){n.setString("Selected",e.getUniqueID().toString());say(p,"Rear coupler selected. Right-click the wagon to connect.");return;}EntityRollingStock head=null;try{head=RailwayWorld.get(e.worldObj,UUID.fromString(n.getString("Selected")));}catch(Exception ignored){}n.removeTag("Selected");say(p,head==null?"Selected vehicle is no longer loaded.":connect(head,e,p));}
 private static void say(EntityPlayer p,String s){p.addChatMessage(new ChatComponentText(s));}
}
